// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 putLock, uint256 putAmount, uint256 collectAmount) internal {
        putAmount = bound(putAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= putAmount);
        try c.SetMinSum(1) {} catch { return; }
        try c.Put{value: putAmount}(putLock) {} catch { return; }
        uint256 beforeBal;
        uint256 beforeUnlock;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { beforeBal = __r0; beforeUnlock = __r1; } catch { return; }
        uint cBalanceBefore = address(c).balance;
        uint256 minSum;
        try c.MinSum() returns (uint256 __r) { minSum = __r; } catch { return; }
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBal;
        uint256 afterUnlock;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { afterBal = __r0; afterUnlock = __r1; } catch { return; }
        uint cBalanceAfter = address(c).balance;
        bool precondsHold = (beforeBal >= minSum) && (beforeBal >= collectAmount) && (block.timestamp > beforeUnlock);
        assertTrue(!(reverted == false && precondsHold) || (afterBal + collectAmount == beforeBal && cBalanceBefore == cBalanceAfter + collectAmount));
    }

    function testFuzz_run(uint256 putLock, uint256 putAmount, uint256 collectAmount) public {
        _run(putLock, putAmount, collectAmount);
    }

    receive() external payable { }
}
